// Package inifmt implements the INI codec, matching `yq -p ini` / `yq -o ini`.
package inifmt

import (
	"fmt"
	"strings"

	"yqclone/yq"
)

// Decode parses INI content into a single document: top-level key/value pairs
// land on the root mapping, each [section] becomes a nested mapping.
// All values are plain strings.
func Decode(data []byte, opts *yq.Opts) ([]*yq.Node, error) {
	root := yq.Mapping(0)
	current := root

	lines := strings.Split(string(data), "\n")
	for i := 0; i < len(lines); i++ {
		line := strings.TrimSuffix(lines[i], "\r")

		trimmed := strings.TrimSpace(line)
		if len(trimmed) == 0 || trimmed[0] == ';' || trimmed[0] == '#' {
			continue
		}

		if trimmed[0] == '[' {
			closeIdx := strings.Index(trimmed, "]")
			if closeIdx < 0 {
				return nil, fmt.Errorf("failed to parse INI content: unclosed section: %s", trimmed)
			}
			name := trimmed[1:closeIdx]
			sec := current.MapGet(name)
			if root.MapGet(name) == nil || root.MapGet(name).Kind != yq.MappingNode {
				sec = yq.Mapping(0)
				root.MapSet(name, sec)
			}
			current = sec
			continue
		}

		// line continuation: trailing backslash joins the next line
		for strings.HasSuffix(line, "\\") && i+1 < len(lines) {
			line = strings.TrimSuffix(line, "\\")
			i++
			line += strings.TrimLeft(strings.TrimSuffix(lines[i], "\r"), " \t")
		}

		key, value, err := parseKeyValue(line, lines, &i)
		if err != nil {
			return nil, err
		}
		current.MapSet(key, yq.Str(value))
	}

	return []*yq.Node{yq.Document(root)}, nil
}

// parseKeyValue splits a logical line into key and value.
func parseKeyValue(line string, lines []string, i *int) (string, string, error) {
	rest := line
	var key string

	if len(rest) > 0 && (rest[0] == '"' || rest[0] == '`') {
		// quoted key: read up to the matching quote
		q := rest[0]
		end := strings.IndexByte(rest[1:], q)
		if end >= 0 {
			key = rest[1 : 1+end]
			rest = rest[1+end+1:]
		}
	}
	if key == "" {
		idx := strings.IndexAny(rest, "=:")
		if idx < 0 {
			return "", "", fmt.Errorf("failed to parse INI content: key-value delimiter not found: %s", strings.TrimSpace(line))
		}
		key = strings.TrimSpace(rest[:idx])
		rest = rest[idx+1:]
	} else {
		idx := strings.IndexAny(rest, "=:")
		if idx < 0 {
			return "", "", fmt.Errorf("failed to parse INI content: key-value delimiter not found: %s", strings.TrimSpace(line))
		}
		rest = rest[idx+1:]
	}

	value := strings.TrimSpace(rest)

	// triple-quoted values may span multiple lines
	if strings.HasPrefix(value, `"""`) || strings.HasPrefix(value, "'''") {
		q := value[:3]
		body := value[3:]
		for {
			if end := strings.Index(body, q); end >= 0 {
				value = body[:end]
				break
			}
			if *i+1 >= len(lines) {
				// unterminated: keep the raw text
				value = value
				break
			}
			*i++
			body += "\n" + strings.TrimSuffix(lines[*i], "\r")
		}
		return key, value, nil
	}

	// backquoted values are literal (comment chars included)
	if strings.HasPrefix(value, "`") {
		if end := strings.IndexByte(value[1:], '`'); end >= 0 {
			return key, value[1 : 1+end], nil
		}
		return key, value, nil
	}

	// strip trailing comments from plain and quoted values
	if idx := strings.IndexAny(value, ";#"); idx >= 0 {
		value = strings.TrimSpace(value[:idx])
	}

	// strip matching surrounding quotes
	if len(value) >= 2 {
		first, last := value[0], value[len(value)-1]
		if first == last && (first == '"' || first == '\'') {
			value = value[1 : len(value)-1]
		}
	}
	return key, value, nil
}

// Encode renders a mapping as INI. Scalar keys are written first
// (`key = value`, aligned), then each map-valued key as a [section].
// Array values and deeper-nested maps are silently dropped.
func Encode(n *yq.Node, opts *yq.Opts) ([]byte, error) {
	if n == nil {
		return nil, fmt.Errorf("INI encoder supports only MappingNode at the root level, got 0")
	}
	if n.Kind == yq.ScalarNode {
		return []byte(scalarText(n)), nil
	}
	root := n.Unwrap()
	if root.Kind != yq.MappingNode {
		return nil, fmt.Errorf("INI encoder supports only MappingNode at the root level, got %d", n.Kind)
	}

	var sb strings.Builder
	firstSection := true

	writeEntries := func(m *yq.Node) {
		names := []string{}
		values := []string{}
		maxLen := 0
		for i := 0; i+1 < len(m.Content); i += 2 {
			k, v := m.Content[i], m.Content[i+1]
			if v.Kind != yq.ScalarNode {
				continue
			}
			name := encodeKeyName(k.Value)
			names = append(names, name)
			values = append(values, encodeValue(scalarText(v)))
			if len(name) > maxLen {
				maxLen = len(name)
			}
		}
		for j, name := range names {
			sb.WriteString(name)
			sb.WriteString(strings.Repeat(" ", maxLen-len(name)))
			sb.WriteString(" = ")
			sb.WriteString(values[j])
			sb.WriteString("\n")
		}
	}

	writeEntries(root)

	for i := 0; i+1 < len(root.Content); i += 2 {
		k, v := root.Content[i], root.Content[i+1]
		if v.Kind != yq.MappingNode {
			continue
		}
		if sb.Len() > 0 || !firstSection {
			sb.WriteString("\n")
		}
		firstSection = false
		sb.WriteString("[")
		sb.WriteString(k.Value)
		sb.WriteString("]\n")
		writeEntries(v)
	}

	return []byte(sb.String()), nil
}

func scalarText(n *yq.Node) string {
	if n.Tag == "!!null" {
		return "null"
	}
	return n.Value
}

// encodeKeyName wraps key names containing quoting-sensitive chars.
func encodeKeyName(name string) string {
	switch {
	case strings.Contains(name, "`"):
		return `"""` + name + `"""`
	case strings.ContainsAny(name, `"=:`):
		return "`" + name + "`"
	default:
		return name
	}
}

// encodeValue applies INI value quoting rules.
func encodeValue(value string) string {
	switch {
	case strings.Contains(value, "\n") || strings.Contains(value, "`"):
		return `"""` + value + `"""`
	case strings.ContainsAny(value, "#;"):
		return "`" + value + "`"
	case strings.TrimSpace(value) != value:
		return `"` + value + `"`
	default:
		return value
	}
}

