package inifmt

import (
	"testing"

	"yqclone/yq"
)

// decodeToString decodes and re-encodes via the YAML-ish debug form:
// we assert on the raw INI encode round trip plus node inspection.
func decodeOne(t *testing.T, input string) *yq.Node {
	t.Helper()
	docs, err := Decode([]byte(input), yq.DefaultOpts())
	if err != nil {
		t.Fatalf("Decode(%q) error: %v", input, err)
	}
	if len(docs) != 1 {
		t.Fatalf("Decode(%q) returned %d docs", input, len(docs))
	}
	return docs[0].Unwrap()
}

func TestDecode(t *testing.T) {
	tests := []struct {
		name  string
		input string
		// expected flattened "path -> value" pairs, in order
		want [][2]string
	}{
		{"basic", "a = 1\nb = hello\n", [][2]string{{"a", "1"}, {"b", "hello"}}},
		{"colon delimiter", "a: 1\nb=2\n", [][2]string{{"a", "1"}, {"b", "2"}}},
		{"colon before equals", "a: b = c\n", [][2]string{{"a", "b = c"}}},
		{"extra equals", "a = x = y\n", [][2]string{{"a", "x = y"}}},
		{"double equals", "a == b\n", [][2]string{{"a", "= b"}}},
		{"value trimmed", "c =  3  \n", [][2]string{{"c", "3"}}},
		{"empty value", "b =\nc = \n", [][2]string{{"b", ""}, {"c", ""}}},
		{"duplicate last wins", "a=1\nb=2\na=3\n", [][2]string{{"a", "3"}, {"b", "2"}}},
		{"comment hash", "e = val#ue\n", [][2]string{{"e", "val"}}},
		{"comment semicolon", "f = a;b\n", [][2]string{{"f", "a"}}},
		{"comment with space", "d = value ; comment\n", [][2]string{{"d", "value"}}},
		{"semicolon in key", "k;e = 1\n", [][2]string{{"k;e", "1"}}},
		{"quoted value", `a = "quoted"` + "\n", [][2]string{{"a", "quoted"}}},
		{"single quoted value", "b = 'sq'\n", [][2]string{{"b", "sq"}}},
		{"backquoted value", "a = `bt;val`\n", [][2]string{{"a", "bt;val"}}},
		{"unmatched quote kept", "a = \"x\n", [][2]string{{"a", "\"x"}}},
		{"quote not at end kept", "b = \"y\"c\n", [][2]string{{"b", "\"y\"c"}}},
		{"comment beats quote", "c = \"with # hash\"\n", [][2]string{{"c", "\"with"}}},
		{"empty double quotes", "a = \"\"\n", [][2]string{{"a", ""}}},
		{"triple single kept", "b = '''\n", [][2]string{{"b", "'''"}}},
		{"quoted key with equals", "`a=b` = 1\n", [][2]string{{"a=b", "1"}}},
		{"quoted key spaces", "\"k k\" = 2\n", [][2]string{{"k k", "2"}}},
		{"single quote key kept", "'sq key' = v\n", [][2]string{{"'sq key'", "v"}}},
		{"continuation", "a = one \\\n  two\n", [][2]string{{"a", "one two"}}},
		{"crlf", "a = x\r\nb = y\r\n", [][2]string{{"a", "x"}, {"b", "y"}}},
		{"indented comments", "  # indented\n  ; also\na = 1\n", [][2]string{{"a", "1"}}},
		{"spaces in key", "k e y : v\n", [][2]string{{"k e y", "v"}}},
		{"triple quoted multiline", "a = \"\"\"line1\nline2\"\"\"\n", [][2]string{{"a", "line1\nline2"}}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			root := decodeOne(t, tc.input)
			if root.Kind != yq.MappingNode {
				t.Fatalf("root kind = %d", root.Kind)
			}
			got := [][2]string{}
			keys := root.MapKeys()
			vals := root.MapValues()
			for i := range keys {
				got = append(got, [2]string{keys[i].Value, vals[i].Value})
			}
			if len(got) != len(tc.want) {
				t.Fatalf("got %v, want %v", got, tc.want)
			}
			for i := range got {
				if got[i] != tc.want[i] {
					t.Fatalf("got %v, want %v", got, tc.want)
				}
			}
			// all decoded values are strings
			for _, v := range vals {
				if v.Tag != "!!str" {
					t.Fatalf("tag = %q, want !!str", v.Tag)
				}
			}
		})
	}
}

func TestDecodeSections(t *testing.T) {
	root := decodeOne(t, "a = 1\n[sec]\nb = 2\nc = 3\n[other]\nd = 4\n")
	if root.MapGet("a").Value != "1" {
		t.Fatalf("a = %v", root.MapGet("a"))
	}
	sec := root.MapGet("sec")
	if sec.Kind != yq.MappingNode || sec.MapGet("b").Value != "2" || sec.MapGet("c").Value != "3" {
		t.Fatalf("sec = %+v", sec)
	}
	if root.MapGet("other").MapGet("d").Value != "4" {
		t.Fatalf("other.d wrong")
	}

	// duplicate sections merge
	root = decodeOne(t, "[sec]\na=1\n[sec]\nb=2\n")
	sec = root.MapGet("sec")
	if sec.MapGet("a").Value != "1" || sec.MapGet("b").Value != "2" {
		t.Fatalf("merged sec = %+v", sec)
	}

	// section names keep spaces, dots are literal
	root = decodeOne(t, "[ SEC ]\na=1\n[sec.sub]\nb=2\n[se;c]\nc=3\n")
	if root.MapGet(" SEC ") == nil || root.MapGet("sec.sub") == nil || root.MapGet("se;c") == nil {
		t.Fatalf("section names: %v", root.MapKeys())
	}

	// empty section
	root = decodeOne(t, "[empty]\n[full]\na=1\n")
	if root.MapGet("empty").Kind != yq.MappingNode || len(root.MapGet("empty").Content) != 0 {
		t.Fatalf("empty section wrong")
	}

	// empty input still yields an empty mapping
	root = decodeOne(t, "")
	if root.Kind != yq.MappingNode || len(root.Content) != 0 {
		t.Fatalf("empty input root = %+v", root)
	}
}

func TestDecodeErrors(t *testing.T) {
	tests := []struct {
		input string
		want  string
	}{
		{"a\n", "failed to parse INI content: key-value delimiter not found: a"},
		{"[bad\n", "failed to parse INI content: unclosed section: [bad"},
	}
	for _, tc := range tests {
		_, err := Decode([]byte(tc.input), yq.DefaultOpts())
		if err == nil || err.Error() != tc.want {
			t.Fatalf("Decode(%q) err = %v, want %q", tc.input, err, tc.want)
		}
	}
}

func encode(t *testing.T, n *yq.Node) string {
	t.Helper()
	out, err := Encode(n, yq.DefaultOpts())
	if err != nil {
		t.Fatalf("Encode error: %v", err)
	}
	return string(out)
}

// build a root mapping from alternating key / *Node values
func rootMap(pairs ...any) *yq.Node {
	m := yq.Mapping(0)
	for i := 0; i < len(pairs); i += 2 {
		m.Content = append(m.Content, yq.Str(pairs[i].(string)), pairs[i+1].(*yq.Node))
	}
	return m
}

func TestEncode(t *testing.T) {
	tests := []struct {
		name string
		root *yq.Node
		want string
	}{
		{"simple", rootMap("a", yq.Str("1")), "a = 1\n"},
		{"scalars before sections",
			rootMap("b", rootMap("z", yq.Str("1")), "a", yq.Str("top"), "c", rootMap("y", yq.Str("2"))),
			"a = top\n\n[b]\nz = 1\n\n[c]\ny = 2\n"},
		{"null bool float",
			rootMap("a", yq.Null(), "b", yq.Bool("true"), "c", yq.Scalar("!!float", "1.5"), "d", yq.Str("sp ace")),
			"a = null\nb = true\nc = 1.5\nd = sp ace\n"},
		{"empty map", rootMap(), ""},
		{"empty section", rootMap("s", rootMap()), "[s]\n"},
		{"arrays dropped", rootMap("sec", rootMap("a", yq.Sequence(0))), "[sec]\n"},
		{"nested maps dropped", rootMap("sec", rootMap("sub", rootMap("x", yq.Int("1")), "b", yq.Int("2"))), "[sec]\nb = 2\n"},
		{"top array dropped", rootMap("top", yq.Sequence(0)), ""},
		{"alignment",
			rootMap("longrootkey", yq.Int("1"), "s", rootMap("a", yq.Int("2"), "bb", yq.Int("3"))),
			"longrootkey = 1\n\n[s]\na  = 2\nbb = 3\n"},
		{"value semicolon", rootMap("a", yq.Str("semi;colon")), "a = `semi;colon`\n"},
		{"value hash", rootMap("b", yq.Str("hash#x")), "b = `hash#x`\n"},
		{"value equals", rootMap("c", yq.Str("eq=ual")), "c = eq=ual\n"},
		{"value leading backquote", rootMap("d", yq.Str("`back")), "d = \"\"\"`back\"\"\"\n"},
		{"value quote inside", rootMap("e", yq.Str("has \"quote\"")), "e = has \"quote\"\n"},
		{"value multiline", rootMap("f", yq.Str("multi\nline")), "f = \"\"\"multi\nline\"\"\"\n"},
		{"value padded", rootMap("g", yq.Str(" plain ")), "g = \" plain \"\n"},
		{"value tab", rootMap("h", yq.Str("x\ty")), "h = x\ty\n"},
		{"key space", rootMap("my key", yq.Str("v")), "my key = v\n"},
		{"key equals", rootMap("a=b", yq.Str("v")), "`a=b` = v\n"},
		{"key colon", rootMap("c:d", yq.Str("v")), "`c:d` = v\n"},
		{"key quote", rootMap("\"q\"", yq.Str("v")), "`\"q\"` = v\n"},
		{"key backquote", rootMap("`bt`", yq.Str("v")), "\"\"\"`bt`\"\"\" = v\n"},
		{"key hash semicolon", rootMap("k#e", yq.Str("v"), "k;e", yq.Str("w")), "k#e = v\nk;e = w\n"},
		{"section names raw",
			rootMap("my sec", rootMap("a", yq.Int("1")), "se;c", rootMap("b", yq.Int("2"))),
			"[my sec]\na = 1\n\n[se;c]\nb = 2\n"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := encode(t, yq.Document(tc.root))
			if got != tc.want {
				t.Fatalf("got %q, want %q", got, tc.want)
			}
		})
	}
}

func TestEncodeNonMapping(t *testing.T) {
	// bare scalars print their value
	out, err := Encode(yq.Document(yq.Str("hello")), yq.DefaultOpts())
	if err != nil || string(out) != "hello" {
		t.Fatalf("scalar: %q, %v", out, err)
	}
	out, err = Encode(yq.Document(yq.Null()), yq.DefaultOpts())
	if err != nil || string(out) != "null" {
		t.Fatalf("null: %q, %v", out, err)
	}
	// arrays are an error
	_, err = Encode(yq.Document(yq.Sequence(0)), yq.DefaultOpts())
	if err == nil || err.Error() != "INI encoder supports only MappingNode at the root level, got 1" {
		t.Fatalf("array err = %v", err)
	}
}

func TestRoundTrip(t *testing.T) {
	input := "a=1\n\n\n[sec]\nb=2\n"
	docs, err := Decode([]byte(input), yq.DefaultOpts())
	if err != nil {
		t.Fatal(err)
	}
	out, err := Encode(docs[0], yq.DefaultOpts())
	if err != nil {
		t.Fatal(err)
	}
	want := "a = 1\n\n[sec]\nb = 2\n"
	if string(out) != want {
		t.Fatalf("got %q, want %q", out, want)
	}
}

